#include <potentiometer.h>
#include "main.h"
#include "button.h"
#include "clock.h"
#include "uart.h"
#include "dfplayer.h"

Button btn_play(GPIOA, 0);
Button btn_next(GPIOA, 1);
Button btn_prev(GPIOA, 4);

UART uart_module(USART2);
DFPlayer player(uart_module);
Potentiometer pot;

int main(void)
{
	// Настройка системного тактирования на 84 МГц и SysTick
	Clock::init(Clock::Source::PLL);

	// Индикаторный светодиод PC13 на плате Blackpill
	RCC->AHB1ENR |= RCC_AHB1ENR_GPIOCEN;
	GPIOC->MODER &= ~(3U << (13 * 2));
	GPIOC->MODER |= (1U << (13 * 2));

	// Инициализация драйверов
	btn_play.init();
	btn_next.init();
	btn_prev.init();
	uart_module.init();
	pot.init();

	// Ожидание запуска DFPlayer
	Clock::delayMs(1000);

	// Установка начальной громкости по текущему положению потенциометра
	uint8_t initial_vol = pot.readVolume(30);
	player.change_volume(initial_vol);

	uint32_t last_pot_time = 0;

    /* Loop forever */
	for (;;) {
		// Опрос кнопок управления воспроизведением
		if (btn_play.wasClicked()) {
			player.toggle();
		}
		if (btn_next.wasClicked()) {
			player.next_track();
		}
		if (btn_prev.wasClicked()) {
			player.prev_track();
		}

		// Неблокирующий опрос потенциометра каждые 150 мс (чтобы не забивать шину UART)
		uint32_t now = Clock::getMillis();
		if (now - last_pot_time >= 150) {
			last_pot_time = now;
			uint8_t new_volume = 0;
			if (pot.hasChanged(new_volume, 30)) {
				player.change_volume(new_volume);
			}
		}
	}
}
